/** Saved depictions: slug, who last saved and how long before the epoch (minutes); bold bond indices where drawn. */
const OVERRIDE_SEED = Object.freeze([
  { slug: "lsd", source: "editor", by: "RIVER", minutesAgo: 60 * 26 },
  { slug: "mdma", source: "editor", by: "MIRA", minutesAgo: 60 * 3, boldBonds: [3, 4] },
  { slug: "caffeine", source: "seeded", by: "SEED", minutesAgo: 60 * 24 * 40 },
  { slug: "ketamine", source: "editor", by: "RIVER", minutesAgo: 60 * 24 * 6 },
  { slug: "psilocybin", source: "seeded", by: "SEED", minutesAgo: 60 * 24 * 40 },
  { slug: "mescaline", source: "template", by: "RIVER", minutesAgo: 60 * 24 * 12 },
  { slug: "2c-b", source: "seeded", by: "SEED", minutesAgo: 60 * 24 * 40 },
  { slug: "cocaine", source: "editor", by: "MIRA", minutesAgo: 60 * 24 * 2 },
  { slug: "morphine", source: "editor", by: "RIVER", minutesAgo: 60 * 24 * 9 },
  { slug: "heroin", source: "seeded", by: "SEED", minutesAgo: 60 * 24 * 40 },
]);

/** The one saved orientation template, drawn from the morphine depiction. */
const TEMPLATE_SEED = Object.freeze([{ classKey: "morphinan", from: "morphine", by: "RIVER", minutesAgo: 60 * 24 * 5 }]);

/** Who saves first under `conflicted`, as the route derives it from their address. */
const CONFLICT_SAVER = "OTHER-ADMIN";

/** A class key from a free-form chemical class ("Benzodiazepines" -> "benzodiazepine"). */
function classKeyOf(value) {
  return String(value).trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").replace(/s$/, "");
}

/** Placeholder markup: the fixture does not render, and the editor re-renders from the MOL block. */
function placeholderSvg(slug) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10" data-fixture="${slug}"></svg>`;
}

/**
 * The molecule routes: the picker, one article's SMILES, class members, the
 * depiction read, save and removal, the template reads and save, and the
 * template apply preview and write.
 *
 * `articles()` returns the editor library rows (slug, title, index
 * categories, classification); `priorityOf(slug)` their priority.
 */
export function createMoleculeRoutes({ fixture, json, toolRead, toolWrite, epoch, articles, priorityOf }) {
  const empty = fixture.state === "empty";
  const iso = (minutesAgo) => new Date(epoch - minutesAgo * 60_000).toISOString();
  let clock = epoch;
  const now = () => (clock += 60_000);
  const overrides = new Map(empty ? [] : OVERRIDE_SEED.map((row) => [row.slug, {
    slug: row.slug,
    molblock: MOLBLOCKS[row.slug],
    svg: SVGS[row.slug] || placeholderSvg(row.slug),
    smiles: MOLECULE_SMILES_SEED[row.slug],
    ...(row.boldBonds ? { boldBonds: [...row.boldBonds] } : {}),
    source: row.source,
    updatedAt: iso(row.minutesAgo),
    updatedBy: row.by,
  }]));
  const templates = new Map(empty ? [] : TEMPLATE_SEED.map((row) => [row.classKey, {
    classKey: row.classKey,
    molblock: MOLBLOCKS[row.from],
    updatedAt: epoch - row.minutesAgo * 60_000,
    updatedBy: row.by,
  }]));
  /** Depictions another admin already saved over, so `conflicted` refuses each first save once. */
  const contested = new Set();
  const admin = () => fixture.role === "admin";
  const refuse = () => json(403, { error: "Admin access required." });
  const saver = () => fixture.session.user.email.split("@")[0].replace(/[^a-z0-9-]/gi, "").toUpperCase();

  const pickerRows = () => (empty ? [] : articles()).map((row) => ({
    slug: row.slug,
    title: row.title,
    priority: priorityOf(row.slug),
    index_categories: row.index_categories ?? [],
    classification: row.classification ?? null,
    hasOverride: overrides.has(row.slug),
  }));
  const page = (rows) => json(200, { page: rows, continueCursor: "", isDone: true });
  const membersOf = (classKey) => pickerRows().filter((row) =>
    (row.classification?.chemical_class ?? []).some((value) => classKeyOf(value) === classKey));

  function saveOverride(body) {
    const slug = typeof body.slug === "string" ? body.slug : "";
    if (!/^(class:)?[a-z0-9][a-z0-9-]*$/.test(slug)) return json(400, { error: "A valid molecule slug is required." });
    if (typeof body.molblock !== "string" || !body.molblock) return json(400, { error: "A valid molecule MOL block is required." });
    if (typeof body.svg !== "string" || !body.svg.includes("<svg")) return json(400, { error: "A valid molecule SVG is required." });
    let stored = overrides.get(slug) ?? null;
    // Under `conflicted`, another admin saves this depiction just before this save lands.
    if (fixture.state === "conflicted" && !contested.has(slug)) {
      contested.add(slug);
      stored = {
        ...(stored ?? { slug, molblock: body.molblock, svg: placeholderSvg(slug) }),
        source: "editor",
        updatedAt: new Date(now()).toISOString(),
        updatedBy: CONFLICT_SAVER,
      };
      overrides.set(slug, stored);
    }
    if (body.expectedUpdatedAt !== undefined && body.expectedUpdatedAt !== (stored?.updatedAt ?? null)) {
      return json(409, {
        error: "Someone saved this depiction after you opened it. Reload it to see their version before saving.",
        conflict: { updatedAt: stored?.updatedAt ?? null, updatedBy: stored?.updatedBy ?? null },
      });
    }
    const row = {
      slug,
      molblock: body.molblock,
      svg: body.svg,
      ...(body.smiles ? { smiles: body.smiles } : {}),
      ...(Array.isArray(body.boldBonds) && body.boldBonds.length ? { boldBonds: [...body.boldBonds] } : {}),
      source: "editor",
      updatedAt: new Date(now()).toISOString(),
      updatedBy: saver(),
    };
    overrides.set(slug, row);
    return json(200, { ok: true, updated: Boolean(stored), slug, updatedAt: row.updatedAt, updatedBy: row.updatedBy });
  }

  return function route({ upper, pathname, params, body }) {
    if (pathname === "/api/dev/molecule-editor" && upper === "GET") {
      if (!admin()) return refuse();
      const scope = params.get("scope");
      const slug = params.get("slug");
      if (scope === "source") {
        return toolRead(() => {
          const row = articles().find((entry) => entry.slug === slug);
          return json(200, row ? { slug, smiles: MOLECULE_SMILES_SEED[slug] ?? "" } : null);
        });
      }
      if (scope === "picker") return toolRead(() => page(pickerRows()));
      if (scope === "class-members") return toolRead(() => page(membersOf(params.get("classKey") ?? "")));
      return json(400, { error: "A supported molecule editor scope is required." });
    }
    if (pathname === "/api/editor/molecule-overrides" && upper === "GET") {
      const slug = params.get("slug");
      if (!slug) return json(200, [...overrides.values()].map(({ slug: key, updatedAt, source }) => ({ slug: key, updatedAt, source })));
      const row = overrides.get(slug);
      if (params.get("scope") === "metadata") return json(200, row ? { slug, updatedAt: row.updatedAt, updatedBy: row.updatedBy, source: row.source } : null);
      return json(200, row ? structuredClone(row) : null);
    }
    if (pathname === "/api/dev/molecule-override") {
      if (!admin()) return refuse();
      if (upper === "GET") return toolRead(() => json(200, { ok: true, override: structuredClone(overrides.get(params.get("slug") ?? "") ?? null) }));
      if (upper === "POST") return toolWrite(() => saveOverride(body ?? {}));
      if (upper === "DELETE") {
        return toolWrite(() => {
          const slug = params.get("slug") ?? "";
          const deleted = overrides.delete(slug);
          return json(200, { ok: true, deleted, slug });
        });
      }
    }
    if (pathname === "/api/dev/molecule-class-template") {
      if (!admin()) return refuse();
      if (upper === "GET") {
        if (params.get("list") === "1") {
          return toolRead(() => json(200, { ok: true, templates: [...templates.values()].map(({ classKey, updatedAt }) => ({ classKey, updatedAt })) }));
        }
        return toolRead(() => json(200, { ok: true, template: structuredClone(templates.get(params.get("classKey") ?? "") ?? null) }));
      }
      if (upper === "POST") {
        return toolWrite(() => {
          const classKey = typeof body?.classKey === "string" ? body.classKey : "";
          if (!classKey || typeof body?.molblock !== "string" || !body.molblock) return json(400, { error: "A valid molecule class template MOL block is required." });
          const row = {
            classKey,
            molblock: body.molblock,
            ...(Array.isArray(body.boldBonds) && body.boldBonds.length ? { boldBonds: [...body.boldBonds] } : {}),
            updatedAt: now(),
            updatedBy: saver(),
          };
          const updated = templates.has(classKey);
          templates.set(classKey, row);
          return json(200, { ok: true, updated, id: `template-${classKey}`, updatedAt: row.updatedAt, updatedBy: row.updatedBy });
        });
      }
    }
    if (pathname === "/api/dev/molecule-class-template/apply") {
      if (!admin()) return refuse();
      if (upper === "GET") {
        return toolRead(() => json(200, {
          ok: true,
          depictions: params.getAll("slug").flatMap((slug) => {
            const row = overrides.get(slug);
            return row ? [{ slug, molblock: row.molblock, source: row.source, ...(row.boldBonds ? { boldBonds: [...row.boldBonds] } : {}) }] : [];
          }),
        }));
      }
      if (upper === "POST") {
        return toolWrite(() => {
          const members = Array.isArray(body?.members) ? body.members : [];
          const results = members.map((member) => {
            const row = overrides.get(member.slug);
            if (row?.source === "editor") return { slug: member.slug, status: "skipped", reason: "A hand edit was saved since the preview." };
            overrides.set(member.slug, { ...(row ?? { slug: member.slug }), molblock: member.molblock, svg: member.svg ?? placeholderSvg(member.slug), source: "template", updatedAt: new Date(now()).toISOString(), updatedBy: saver() });
            return { slug: member.slug, status: "applied" };
          });
          return json(200, { ok: true, results, summary: { applied: results.filter((r) => r.status === "applied").length, protected: results.filter((r) => r.status === "skipped").length, errors: 0 } });
        });
      }
    }
    return null;
  };
}
